use crate::{bq061 as b,catalog,model::*,rules::*,unit_support::*};
fn grave(g:&mut Game,id:&str,seat:usize)->String {let c=g.make_card(id,seat);let id=c.id.clone();g.players[seat].graveyard.push(c);id}
fn setup()->(Game,String){let mut g=game();fund(&mut g,0,"JC069",1);let id=held(&mut g,b::ID,0);(g,id)}
fn play(id:&str)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),..Action::new("play")}}
fn top(g:&mut Game){crate::jc029_tests::pass_top(g);}
fn bad(reference:&Game,g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(reference);r.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq061_original_closed_definition_and_program_transplants(){let c=catalog::card(b::ID);assert_eq!((c.cost,c.color.as_str(),c.supported),(1,"灰",false));assert_eq!(c.loyalty,["灰色"]);assert_eq!(c.subtypes,["策略"]);assert!(b::definition().abilities[0].play_only);for n in 0..5{let mut d=b::definition();let a=&mut d.abilities[0];match n{0=>a.ops.clear(),1=>a.play_only=false,2=>a.timing=Timing::Fast,3=>a.targets.push(target(Zone::Board,EntityKind::Any,Relation::Any,Range::Anywhere)),_=>a.ops.push(Op::BQ061Recover)};assert!(b::validate_definition(b::ID,&d).is_err());}assert!(b::validate_definition("JC001",&b::definition()).is_err());}
#[test]fn bq061_paid_mandatory_one_plan_or_command_and_no_all_recovery(){for id in ["WM046","BQ064"]{let(mut g,source)=setup();let pick=grave(&mut g,id,0);let other=grave(&mut g,"BQ048",0);grave(&mut g,"JC125",0);grave(&mut g,"BQ064",1);act(&mut g,0,play(&source));assert_eq!(g.resources(0),0);top(&mut g);let p=g.pending.clone().unwrap();assert_eq!((p.choice.min,p.choice.max,p.choice.allow_decline),(Some(1),Some(1),Some(false)));assert_eq!(p.choice.options.len(),2);reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![]),..Action::new("choose")});reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![pick.clone(),other.clone()]),..Action::new("choose")});choose(&mut g,vec![pick.clone()]);assert!(g.players[0].hand.iter().any(|c|c.definition==id&&c.id!=pick));assert!(g.players[0].graveyard.iter().any(|c|c.id==other));assert!(g.pending.is_none());restore(&mut g);}}
#[test]fn bq061_empty_or_ineligible_grave_still_pays_without_choice_or_draw(){for nonempty in [false,true]{let(mut g,source)=setup();if nonempty{grave(&mut g,"JC125",0);}let hand=g.players[0].hand.len();let deck=g.players[0].deck.len();act(&mut g,0,play(&source));top(&mut g);assert!(g.pending.is_none());assert_eq!(g.resources(0),0);assert_eq!(g.players[0].hand.len(),hand-1);assert_eq!(g.players[0].deck.len(),deck);assert!(g.players[0].graveyard.iter().any(|c|c.definition==b::ID));restore(&mut g);}}
#[test]fn bq061_payment_loyalty_target_and_command_payload_reject_atomically(){let(mut g,id)=setup();let mut a=play(&id);a.target_id=Some("p0".into());reject(&mut g,0,a);let mut a=play(&id);a.option=Some("all".into());reject(&mut g,0,a);g.players[0].assets.clear();reject(&mut g,0,play(&id));fund(&mut g,0,"JC002",1);reject(&mut g,0,play(&id));}
#[test]fn bq061_resolves_current_grave_not_preselected_instances(){let(mut g,source)=setup();let old=grave(&mut g,"BQ064",0);act(&mut g,0,play(&source));let c=g.players[0].graveyard.remove(0);g.players[0].hand.push(c);let new=grave(&mut g,"BQ048",0);restore(&mut g);top(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>(),[new.clone()]);let p=g.pending.clone().unwrap();reject(&mut g,0,Action{choice_id:Some(p.choice.id),selected:Some(vec![old]),..Action::new("choose")});choose(&mut g,vec![new]);}
#[test]fn bq061_restore_rejects_missing_foreign_frames_payment_and_pending_corruption(){let(mut g,id)=setup();grave(&mut g,"BQ064",0);act(&mut g,0,play(&id));for n in 0..5{let mut x=g.clone();let i=x.stack.last_mut().unwrap();if n==0{i.frame=None;}else{let f=i.frame.as_mut().unwrap();match n{1=>f.source.card.definition="JC001".into(),2=>f.steps.clear(),3=>f.already_paid.clear(),_=>f.steps[0].context=1}}bad(&g,&x);}top(&mut g);for n in 0..6{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(0),1=>p.choice.max=Some(2),2=>p.seat=1,3=>p.choice.options.clear(),4=>p.choice.allow_decline=Some(true),_=>if let ChoiceResolution::Frame{frame,..}=&mut p.resolution{frame.source.card.definition="JC001".into();}}bad(&g,&x);}let mut x=g.clone();let ChoiceResolution::Frame{frame,..}=&g.pending.as_ref().unwrap().resolution else{panic!()};x.effects.push_back(Effect::Frame{frame:frame.clone()});bad(&g,&x);restore(&mut g);}
#[test]fn bq061_printed_mystic_five_is_added_to_cost_one(){let mut g=game();fund(&mut g,0,"JC125",2);let spell=held(&mut g,"BQ090",0);for seat in 0..4{held(&mut g,if seat==0{b::ID}else{"JC125"},seat);}act(&mut g,0,Action{card_id:Some(spell),ability_id:Some(crate::import20_contest::HAND.into()),..Action::new("activate")});top(&mut g);for seat in 0..4{let id=g.players[seat].hand.iter().find(|c|c.definition==if seat==0{b::ID}else{"JC125"}).unwrap().id.clone();choose(&mut g,vec![id]);}while g.pending.as_ref().is_some_and(|p|p.choice.kind==crate::mystic_contest::REWARD_KIND){choose(&mut g,vec![]);}assert_eq!(g.mystic_history[0].shown[0].value,6);restore(&mut g);}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(s["command"].clone()).unwrap();let d=room.transition(s["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn prepared(empty:bool,index:usize)->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(mut g,id)=setup();if !empty{grave(&mut g,"WM046",0);grave(&mut g,"BQ064",0);}let mut t=Trace::new_preserving_rng(g,format!("bq061-prepared-{}",if empty{"empty"}else{"mandatory"}),index);t.action(0,play(&id));for _ in 0..50{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}assert!(t.room.game.pending.is_none());duplicate(t.value())}
fn constructed(seed:u64)->(Game,crate::deck::DeckDraft){let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-bq061-natural".into();d.name="钻研故纸堆私有输入".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("XG21",3),("JC069",3),("BQ064",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(crate::deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID,"XG21"].contains(&c.id.as_str()){c.supported=true;}}let d=crate::deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=crate::deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=crate::deck::validate(other).unwrap();let mut g=Game::new("bq061-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
fn natural()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..2049).find_map(|seed|{let(g,d)=constructed(seed);let h=&g.players[0].hand;(h.iter().any(|c|c.definition==b::ID)&&h.iter().any(|c|c.definition=="XG21")&&h.iter().any(|c|matches!(c.definition.as_str(),"JC069"|"WM046"|"BQ064"))).then_some((seed,g,d))}).expect("bounded real dealt gray hand");let mut t=Trace::new_preserving_rng(g,"bq061-natural-plan-paid-sacrifice-and-recover".into(),710);let mut recovered=false;let mut played=false;for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){let ours=matches!(p.resolution,ChoiceResolution::Frame{choice:FrameChoice::BQ061Recover,..});let ids=if ours{vec![p.choice.options.iter().find(|o|t.room.game.players[0].graveyard.iter().any(|c|c.id==o.id&&c.definition=="XG21")).unwrap().id.clone()]}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(ids);if ours{recovered=true;}continue;}if recovered&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.is_empty(){legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&matches!(c.definition.as_str(),"JC069"|"WM046"|"BQ064"))))}else if g.players[0].graveyard.iter().any(|c|c.definition=="XG21")&&!played{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::batch4_phantom::KEY)).or_else(||legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="XG21"))))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(b::KEY){played=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(recovered&&played,"natural gray chain did not finish");assert!(t.room.game.players[0].hand.iter().any(|c|c.definition=="XG21"));let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"privateRegistryOnly":true,"privateRegistryCandidates":[b::ID,"XG21"],"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn bq061_native_natural_and_prepared_room_export(){let cases=vec![natural(),prepared(false,711),prepared(true,712)];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq061.rs",include_bytes!("bq061.rs").as_slice()),("rust-game/src/bq061_tests.rs",include_bytes!("bq061_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("BQ061_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}
